      //   .catch((e) => {
      //     this.extra_message = e;
      //     this.loginError = true;
      //   });
    }
  }
  
  public authenticate() {
    const payload = {
      username: this.username,
      password: this.password,
    };
    axios
      .post(this.$store.state.endpoints.obtainJWT, payload)
      .then((response) => {
        console.log(response);
        this.$store.commit("updateToken", response.data.access);
        // get and set auth user
        const base = {
          baseURL: (window as any).API_BASE_URL || '/',
          headers: {
            // Set your Authorization to 'JWT', not Bearer!!!
            Authorization: `Bearer ${this.$store.state.jwt}`,
            "Content-Type": "application/json",
          },
          xhrFields: {
            withCredentials: true,
          },
        };

        const authRequest = axios.create({
          baseURL: (window as any).API_BASE_URL || '/',
          timeout: 5000,
          headers: {
            Authorization: `Bearer ${this.$store.state.jwt}`,
            'Content-Type': 'application/json',
          },
        });

        const ping = () => {
          return authRequest.get('it/api/ping/', { params: { id: 'PONG' } })
          .then((response) => Promise.resolve(response.data))
          .catch((error) => Promise.reject(error));
        };

        ping().then((id)=> console.log(id) );

        // Even though the authentication returned a user object that can be
        // decoded, we fetch it again. This way we aren't super dependant on
        // JWT and can plug in something else.
        // const axiosInstance = axios.create(base);
        // axiosInstance({
        //   url: "/user/",
        //   method: "get",
        //   params: {},
        // }).then((response) => {
        //   this.$store.commit("setAuthUser", {
        //     authUser: response.data,
        //     isAuthenticated: true,
        //   });
        //   this.$router.push({ name: "Home" });
        // });
      })
      .catch((error) => {
        this.loginError = true;
        console.log(error);
        console.debug(error);
        console.dir(error);
      });
    }
}
