import group from '@/store/group';
import info from '@/store/info';
import me from '@/store/me';
import menu from '@/store/menu';
import modal from '@/store/modal';
import settings from '@/store/settings';
import { IRootState } from '@/types/IRootState';
import Vue from 'vue';
import Vuex, { StoreOptions } from 'vuex';

Vue.use(Vuex);

const store: StoreOptions<IRootState> = {
  state: {
    showLoader: false,
    errors: [],
    authUser: {},
    isAuthenticated: false,
    jwt: localStorage.getItem("token"),
    endpoints: {
      // TODO: Remove hardcoding of dev endpoints
      obtainJWT: "http://localhost:8081/it/api/token/",
      refreshJWT: "http://localhost:8081/it/api/token/refresh/",
      // baseUrl: "https://127.0.0.1:8000/api/v1/",
    },
  },
  modules: {
    info,
    group,
    me,
    modal,
    menu,
    settings,
  },
  getters: {
    showLoader(state): boolean {
      return state.showLoader;
    },
    errors(state): string[] {
      return state.errors;
    },
  },
  actions: {
    showLoader({commit}) {
      commit('setLoader', true);
    },
    hideLoader({commit}) {
      commit('setLoader', false);
    },
    addError({commit}, error) {
      commit('addError', error);
    },
    removeErrors({commit}) {
      commit('removeErrors');
    },
  },
  mutations: {
    setLoader(state, show) {
      state.showLoader = show;
    },
    addError(state, error: string) {
      state.errors.push(error);
    },
    removeErrors(state) {
      state.errors = [];
    },
    setAuthUser(state, { authUser, isAuthenticated }) {
      Vue.set(state, "authUser", authUser);
      Vue.set(state, "isAuthenticated", isAuthenticated);
    },
    updateToken(state, newToken) {
      // TODO: For security purposes, take localStorage out of the project.
      localStorage.setItem("token", newToken);
      state.jwt = newToken;
    },
    removeToken(state) {
      // TODO: For security purposes, take localStorage out of the project.
      localStorage.removeItem("token");
      state.jwt = null;
    },
  },
};

export default new Vuex.Store(store);
